/*
Contains the seed data to generate the us_ecommerce_data_set
The data set (customers w. addresses and orders) will be fully instantiated using the seed data and stored as part of the sample GitHub
This will make all examples in the book reproducible
The seed data will be stored in its own schema us_data_seed

* us_first_name_seed 
* us_last_name
* us_address_seed


*/

\c us_ecommerce_data

\echo '*** creating schema us_data_seed ***'
CREATE SCHEMA IF NOT EXISTS us_data_seed;

CREATE TABLE  IF NOT EXISTS us_data_seed.us_first_name_seed (
    name VARCHAR(50) NOT NULL
);

